                # Start of a new image
                queue = [(i, j)]
                image = []
                visited[i][j] = True

                while queue:
                    x, y = queue.pop()
                    image.append((x, y))

                    for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < H and 0 <= ny < W and page[nx][ny] == '+' and not visited[nx][ny]:
