import sys

def is_ad(image):
    allowed_chars = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789?!,. ")
    for row in image:
        for char in row:
            if char not in allowed_chars:
                return True
    return False

def find_images(page, H, W):
    images = []
    visited = [[False] * W for _ in range(H)]

    for i in range(1, H - 1):
        for j in range(1, W - 1):
            if page[i][j] == '+' and not visited[i][j]:
                image = []
                stack = [(i, j)]

                while stack:
                    x, y = stack.pop()
                    if visited[x][y]:
                        continue
                    visited[x][y] = True
                    image.append((x, y))

                    for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < H and 0 <= ny < W and page[nx][ny] == '+':
                            stack.append((nx, ny))

                images.append(image)

    return images

def get_image_content(page, image):
    min_x = min(x for x, y in image)
    max_x = max(x for x, y in image)
    min_y = min(y for x, y in image)
    max_y = max(y for x, y in image)

    content = []
    for i in range(min_x, max_x + 1):
        row = []
        for j in range(min_y, max_y + 1):
            row.append(page[i][j])
        content.append(''.join(row))

    return content

def remove_ads(page, H, W):
    images = find_images(page, H, W)
    ads = []

    for image in images:
        content = get_image_content(page, image)
        if is_ad(content):
            ads.append((image, len(content) * len(content[0])))

    if ads:
        ads.sort(key=lambda x: x[1])
        smallest_ad_image, _ = ads[0]

        for x, y in smallest_ad_image:
            page[x] = page[x][:y] + ' ' + page[x][y+1:]

    return page

def main():
    import sys
    input = sys.stdin.read
    data = input().splitlines()

    H, W = map(int, data[0].split())
    page = data[1:]

    result = remove_ads(page, H, W)
    for line in result:
        print(line)

if __name__ == "__main__":
